SELECT 
FROM devices d
WHERE d.device_uuid = #{deviceUuid}
    AND d.organization_id = #{organizationId}

SELECT FROM devices d WHERE d.organization_id = #{organizationId} AND d.type_id = #{typeId}
AND EXISTS ( SELECT 1 FROM location_devices ld JOIN locations l ON l.location_id = ld.location_id WHERE ld.device_uuid = d.device_uuid AND ld.location_id = #{locationId} AND (ld.end_date IS NULL OR ld.end_date > NOW()) AND l.deleted_at IS NULL )
ORDER BY d.device_name, d.device_uuid

SELECT dcs.device_uuid, dcs.current_state, dcs.measured_at, dcs.received_at
FROM device_current_states dcs
JOIN devices d ON d.device_uuid = dcs.device_uuid
WHERE d.organization_id = #{organizationId}
    AND dcs.device_uuid = #{deviceUuid}

SELECT device_uuid, current_state, measured_at, received_at
FROM device_current_states
WHERE device_uuid = #{deviceUuid}

