mapper.select:
SELECT 
FROM location_devices ld
JOIN devices d ON d.device_uuid = ld.device_uuid
JOIN locations l ON l.location_id = ld.location_id
WHERE d.organization_id = #{organizationId}
    AND l.organization_id = #{organizationId}
    AND (ld.end_date IS NULL OR ld.end_date > NOW())
    AND l.deleted_at IS NULL
AND d.type_id = #{typeId}
AND ld.location_id = #{locationId}
ORDER BY d.device_name, d.device_uuid

