UPDATE devices SET
    type_id = #{typeId},
    device_name = #{deviceName},
    serial_number = #{serialNumber},
    model = #{model},
    vendor = #{vendor},
    manufacturer = #{manufacturer}
WHERE device_uuid = #{deviceUuid}
    AND organization_id = #{organizationId}

mapper.insert:
INSERT INTO location_devices (device_uuid, location_id, start_date, end_date)
SELECT #{deviceUuid}, #{locationId}, #{startDate}, #{endDate}
WHERE NOT EXISTS (
    SELECT 1 FROM location_devices
    WHERE device_uuid = #{deviceUuid}
        AND (end_date IS NULL OR end_date > NOW())
)

mapper.select:
SELECT 
FROM location_devices ld
JOIN devices d ON d.device_uuid = ld.device_uuid
JOIN locations l ON l.location_id = ld.location_id
WHERE d.organization_id = #{organizationId}
    AND ld.device_uuid = #{deviceUuid}
    AND l.organization_id = #{organizationId}
AND ld.location_id = #{locationId}
    AND (ld.end_date IS NULL OR ld.end_date > NOW())
    AND l.deleted_at IS NULL

SELECT EXISTS (
    SELECT 1
    FROM location_devices
    WHERE location_id = #{locationId}
        AND (end_date IS NULL OR end_date > NOW())
)

mapper.update:
UPDATE location_devices SET end_date = NOW()
WHERE device_uuid = #{deviceUuid}
    AND location_id = #{locationId}
    AND (end_date IS NULL OR end_date > NOW())
